using DSWI_T1_1.Dtos;using DSWI_T1_1.Models;using DSWI_T1_1.Repositories.Interfaces;using DSWI_T1_1.Services.Interfaces;namespace DSWI_T1_1.Services.Implementations;public class CitaService:ICitaService{private readonly ICitaRepository r;public CitaService(ICitaRepository x)=>r=x;public async Task<IReadOnlyList<CitaDto>> ObtenerTodosAsync()=>(await r.ObtenerTodosAsync()).Select(Map).ToList();public async Task<CitaDto?> ObtenerPorIdAsync(int id){var c=await r.ObtenerPorIdAsync(id);return c==null?null:Map(c);}public Task<int> CrearAsync(CitaDto d)=>r.CrearAsync(Convertir(d));public async Task<bool> EditarAsync(CitaDto d){if(await r.ObtenerPorIdAsync(d.CitaID)==null)return false;return await r.EditarAsync(Convertir(d));}private static Cita Convertir(CitaDto d)=>new(){CitaID=d.CitaID,Fecha=d.Fecha?.Date,Hora=d.Hora,Especialidad=d.Especialidad.Trim(),Estado=d.Estado,PacienteID=d.PacienteID};private static CitaDto Map(Cita c)=>new(){CitaID=c.CitaID,Fecha=c.Fecha,Hora=c.Hora,Especialidad=c.Especialidad??"",Estado=c.Estado??"",PacienteID=c.PacienteID};}